152	#[derive(Debug, PartialEq, Eq, Clone)]
153	enum ParseState<'a> {
154	    /// Parsing a value done, there is no state to record.
155	    ValueDone,
156	
157	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
158	    Pos((usize, usize)),
159	
160	    /// Parsing a optional flag argument
161	    Opt((&'a clap::Arg, usize)),
162	}
