164	fn complete_arg(
165	    arg: &clap_lex::ParsedArg<'_>,
166	    cmd: &clap::Command,
167	    current_dir: Option<&std::path::Path>,
168	    pos_index: usize,
169	    is_escaped: bool,
170	    state: ParseState<'_>,
171	    disabled: &HashSet<Id>,
172	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
173	    debug!(
174	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
175	        arg,
176	        cmd.get_name(),
177	        current_dir,
178	        pos_index,
179	        state
180	    );
181	    let mut completions = Vec::<CompletionCandidate>::new();
182	
183	    match state {
184	        ParseState::ValueDone => {
185	            // After `--`, only positional arguments are completed.
186	            if !is_escaped {
187	                if let Ok(value) = arg.to_value() {
188	                    completions.extend(complete_subcommand(value, cmd));
189	                }
190	            }
191	
192	            if let Some(positional) = cmd
193	                .get_positionals()
194	                .find(|p| p.get_index() == Some(pos_index))
195	            {
196	                if !disabled.contains(positional.get_id()) {
197	                    completions.extend(complete_arg_value(
198	                        arg.to_value(),
199	                        positional,
200	                        current_dir,
201	                        0,
202	                    ));
203	                }
204	            }
205	            if !is_escaped {
206	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
207	            }
208	        }
209	        ParseState::Pos((_, num_arg)) => {
210	            if let Some(positional) = cmd
211	                .get_positionals()
212	                .find(|p| p.get_index() == Some(pos_index))
213	            {
214	                if !disabled.contains(positional.get_id()) {
215	                    completions.extend(complete_arg_value(
216	                        arg.to_value(),
217	                        positional,
218	                        current_dir,
219	                        num_arg.saturating_sub(1),
220	                    ));
221	                }
222	                if !is_escaped
223	                    && positional
224	                        .get_num_args()
225	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
226	                {
227	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
228	                }
229	            }
230	        }
231	        ParseState::Opt((opt, count)) => {
232	            if !disabled.contains(opt.get_id()) {
233	                completions.extend(complete_arg_value(
234	                    arg.to_value(),
235	                    opt,
236	                    current_dir,
237	                    count.saturating_sub(1),
238	                ));
239	            }
240	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
241	            if count > min {
242	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
243	                completions.extend(complete_arg(
244	                    arg,
245	                    cmd,
246	                    current_dir,
247	                    pos_index,
248	                    is_escaped,
249	                    ParseState::ValueDone,
250	                    disabled,
251	                )?);
252	            }
253	        }
254	    }
255	    if completions.iter().any(|a| !a.is_hide_set()) {
256	        completions.retain(|a| !a.is_hide_set());
257	    }
258	    let mut seen_ids = HashSet::new();
259	    completions.retain(move |a| {
260	        if let Some(id) = a.get_id().cloned() {
261	            seen_ids.insert(id)
262	        } else {
263	            true
264	        }
265	    });
266	
267	    let mut tags = Vec::new();
268	    for candidate in &completions {
269	        let tag = candidate.get_tag().cloned();
270	        if !tags.contains(&tag) {
271	            tags.push(tag);
272	        }
273	    }
274	    completions.sort_by_key(|c| {
275	        (
276	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
277	            c.get_display_order(),
278	        )
279	    });
280	
281	    Ok(completions)
282	}
