284	fn complete_option(
285	    arg: &clap_lex::ParsedArg<'_>,
286	    cmd: &clap::Command,
287	    current_dir: Option<&std::path::Path>,
288	    disabled: &HashSet<Id>,
289	) -> Vec<CompletionCandidate> {
290	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
291	    let mut completions = Vec::<CompletionCandidate>::new();
292	    if arg.is_empty() {
293	        completions.extend(longs_and_visible_aliases(cmd, disabled));
294	        completions.extend(hidden_longs_aliases(cmd, disabled));
295	
296	        let dash_or_arg = if arg.is_empty() {
297	            "-".into()
298	        } else {
299	            arg.to_value_os().to_string_lossy()
300	        };
301	        completions.extend(
302	            shorts_and_visible_aliases(cmd, disabled)
303	                .into_iter()
304	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
305	        );
306	    } else if arg.is_stdio() {
307	        // HACK: Assuming knowledge of is_stdio
308	        let dash_or_arg = if arg.is_empty() {
309	            "-".into()
310	        } else {
311	            arg.to_value_os().to_string_lossy()
312	        };
313	        completions.extend(
314	            shorts_and_visible_aliases(cmd, disabled)
315	                .into_iter()
316	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
317	        );
318	
319	        completions.extend(longs_and_visible_aliases(cmd, disabled));
320	        completions.extend(hidden_longs_aliases(cmd, disabled));
321	    } else if arg.is_escape() {
322	        // HACK: Assuming knowledge of is_escape
323	        completions.extend(longs_and_visible_aliases(cmd, disabled));
324	        completions.extend(hidden_longs_aliases(cmd, disabled));
325	    } else if let Some((flag, value)) = arg.to_long() {
326	        if let Ok(flag) = flag {
327	            if let Some(value) = value {
328	                let opt = cmd.get_arguments().find(|a| {
329	                    a.get_long_and_visible_aliases()
330	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
331	                });
332	                if let Some(arg) = opt {
333	                    if !disabled.contains(arg.get_id()) {
334	                        completions.extend(
335	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
336	                                .into_iter()
337	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
338	                        );
339	                    }
340	                }
341	            } else {
342	                completions.extend(
343	                    longs_and_visible_aliases(cmd, disabled)
344	                        .into_iter()
345	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
346	                );
347	                completions.extend(
348	                    hidden_longs_aliases(cmd, disabled)
349	                        .into_iter()
350	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
351	                );
352	            }
353	        }
354	    } else if let Some(short) = arg.to_short() {
355	        if !short.is_negative_number() {
356	            // Find the first takes_values option.
357	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
358	
359	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
360	            if let Some(opt) = takes_value_opt {
361	                if !disabled.contains(opt.get_id()) {
362	                    let mut peek_short = short.clone();
363	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
364	                        short.next_flag();
365	                        true
366	                    } else {
367	                        false
368	                    };
369	
370	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
371	                    completions.extend(
372	                        complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
373	                            .into_iter()
374	                            .map(|comp| {
375	                                let sep = if has_equal { "=" } else { "" };
376	                                comp.add_prefix(format!("-{leading_flags}{sep}"))
377	                            }),
378	                    );
379	                }
380	            } else {
381	                completions.extend(
382	                    shorts_and_visible_aliases(cmd, disabled)
383	                        .into_iter()
384	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
385	                );
386	            }
387	        }
388	    }
389	    debug!("complete_option: completions={completions:?}");
390	    completions
391	}
