393	fn complete_arg_value(
394	    value: Result<&str, &OsStr>,
395	    arg: &clap::Arg,
396	    current_dir: Option<&std::path::Path>,
397	    arg_index: usize,
398	) -> Vec<CompletionCandidate> {
399	    let mut values = Vec::new();
400	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
401	
402	    let (prefix, value) =
403	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
404	
405	    let value_os = match value {
406	        Ok(value) => OsStr::new(value),
407	        Err(value_os) => value_os,
408	    };
409	
410	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
411	        values.extend(completer.complete_at(arg_index, value_os));
412	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
413	        values.extend(complete_value_candidates(
414	            value_os,
415	            completer.value_candidates(),
416	        ));
417	    } else if let Some(possible_values) = possible_values(arg) {
418	        if let Ok(value) = value {
419	            values.extend(complete_candidates_str(
420	                value,
421	                possible_value_candidates(possible_values),
422	            ));
423	        }
424	    } else {
425	        match arg.get_value_hint() {
426	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
427	                // Should not complete
428	            }
429	            clap::ValueHint::AnyPath => {
430	                values.extend(complete_path(value_os, current_dir, &|_| true));
431	            }
432	            clap::ValueHint::FilePath => {
433	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
434	            }
435	            clap::ValueHint::DirPath => {
436	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
437	            }
438	            clap::ValueHint::ExecutablePath => {
439	                use is_executable::IsExecutable;
440	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
441	            }
442	            clap::ValueHint::CommandName
443	            | clap::ValueHint::CommandString
444	            | clap::ValueHint::CommandWithArguments
445	            | clap::ValueHint::Username
446	            | clap::ValueHint::Hostname
447	            | clap::ValueHint::Url
448	            | clap::ValueHint::EmailAddress => {
449	                // No completion implementation
450	            }
451	            _ => {
452	                // Safe-ish fallback
453	                values.extend(complete_path(value_os, current_dir, &|_| true));
454	            }
455	        }
456	
457	        values.sort();
458	    }
459	
460	    if let Some(prefix) = prefix {
461	        values = values
462	            .into_iter()
463	            .map(|comp| comp.add_prefix(prefix))
464	            .collect();
465	    }
466	    values = values
467	        .into_iter()
468	        .map(|comp| {
469	            if comp.get_tag().is_some() {
470	                comp
471	            } else {
472	                comp.tag(Some(arg.to_string().into()))
473	            }
474	        })
475	        .collect();
476	
477	    debug!("complete_arg_value: values={values:?}");
478	    values
479	}
