481	fn rsplit_delimiter<'s, 'o>(
482	    value: Result<&'s str, &'o OsStr>,
483	    delimiter: Option<char>,
484	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
485	    let delimiter = delimiter?;
486	    let value = value.ok()?;
487	    let pos = value.rfind(delimiter)?;
488	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
489	    Some((Some(prefix), Ok(value)))
490	}
