492	fn complete_value_candidates(
493	    value: &OsStr,
494	    completer: &dyn ValueCandidates,
495	) -> Vec<CompletionCandidate> {
496	    debug!("complete_value_candidates: value={value:?}");
497	
498	    let mut values = completer.candidates();
499	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
500	    values
501	}
