503	fn complete_candidates_str(
504	    value: &str,
505	    mut values: Vec<CompletionCandidate>,
506	) -> Vec<CompletionCandidate> {
507	    debug!("complete_candidates_str: value={value:?}");
508	
509	    values.retain(|comp| comp.get_value().starts_with(value));
510	    values
511	}
