513	fn complete_value_candidates_str(
514	    value: &str,
515	    completer: &dyn ValueCandidates,
516	) -> Vec<CompletionCandidate> {
517	    debug!("complete_value_candidates_str: value={value:?}");
518	
519	    complete_candidates_str(value, completer.candidates())
520	}
