522	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
523	    debug!(
524	        "complete_subcommand: cmd={:?}, value={:?}",
525	        cmd.get_name(),
526	        value
527	    );
528	
529	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
530	        .into_iter()
531	        .filter(|x| x.get_value().starts_with(value))
532	        .collect();
533	    if cmd.is_allow_external_subcommands_set() {
534	        let external_completer = cmd.get::<SubcommandCandidates>();
535	        if let Some(completer) = external_completer {
536	            scs.extend(complete_value_candidates_str(
537	                value,
538	                completer.value_candidates(),
539	            ));
540	        }
541	    }
542	
543	    scs.sort();
544	    scs.dedup();
545	    scs
546	}
