548	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
549	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
550	fn longs_and_visible_aliases(
551	    p: &clap::Command,
552	    disabled: &HashSet<Id>,
553	) -> Vec<CompletionCandidate> {
554	    debug!("longs: name={}", p.get_name());
555	
556	    p.get_arguments()
557	        .filter(|a| !disabled.contains(a.get_id()))
558	        .filter_map(|a| {
559	            a.get_long_and_visible_aliases().map(|longs| {
560	                longs
561	                    .into_iter()
562	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
563	            })
564	        })
565	        .flatten()
566	        .collect()
567	}
