569	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
570	fn hidden_longs_aliases(p: &clap::Command, disabled: &HashSet<Id>) -> Vec<CompletionCandidate> {
571	    debug!("longs: name={}", p.get_name());
572	
573	    p.get_arguments()
574	        .filter(|a| !disabled.contains(a.get_id()))
575	        .filter_map(|a| {
576	            a.get_aliases().map(|longs| {
577	                longs.into_iter().map(|s| {
578	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
579	                })
580	            })
581	        })
582	        .flatten()
583	        .collect()
584	}
