586	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
587	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
588	fn shorts_and_visible_aliases(
589	    p: &clap::Command,
590	    disabled: &HashSet<Id>,
591	) -> Vec<CompletionCandidate> {
592	    debug!("shorts: name={}", p.get_name());
593	
594	    p.get_arguments()
595	        .filter(|a| !disabled.contains(a.get_id()))
596	        .filter_map(|a| {
597	            a.get_short_and_visible_aliases().map(|shorts| {
598	                shorts.into_iter().map(|s| {
599	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
600	                        a.get_help()
601	                            .cloned()
602	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
603	                    )
604	                })
605	            })
606	        })
607	        .flatten()
608	        .collect()
609	}
