611	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
612	    candidate
613	        .help(arg.get_help().cloned())
614	        .id(Some(format!("arg::{}", arg.get_id())))
615	        .tag(Some(
616	            arg.get_help_heading()
617	                .unwrap_or("Options")
618	                .to_owned()
619	                .into(),
620	        ))
621	        .display_order(Some(arg.get_display_order()))
622	        .hide(arg.is_hide_set())
623	}
624	
625	/// Get the possible values for completion
626	fn possible_values(
627	    a: &clap::Arg,
628	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
629	    if !a.get_num_args().expect("built").takes_values() {
630	        None
631	    } else {
632	        a.get_value_parser().possible_values()
633	    }
634	}
635	
636	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
637	///
638	/// Subcommand `rustup toolchain install` would be converted to
639	/// `("install", "rustup toolchain install")`.
640	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
641	    debug!("subcommands: name={}", p.get_name());
642	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
643	    p.get_subcommands()
644	        .flat_map(|sc| {
645	            sc.get_name_and_visible_aliases()
646	                .into_iter()
647	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
648	                .chain(sc.get_aliases().map(|s| {
649	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
650	                        .hide(true)
651	                }))
652	        })
653	        .collect()
654	}
655	
656	fn populate_command_candidate(
657	    candidate: CompletionCandidate,
658	    cmd: &clap::Command,
659	    subcommand: &clap::Command,
660	) -> CompletionCandidate {
661	    candidate
662	        .help(subcommand.get_about().cloned())
663	        .id(Some(format!("command::{}", subcommand.get_name())))
664	        .tag(Some(
665	            cmd.get_subcommand_help_heading()
666	                .unwrap_or("Commands")
667	                .to_owned()
668	                .into(),
669	        ))
670	        .display_order(Some(subcommand.get_display_order()))
671	        .hide(subcommand.is_hide_set())
672	}
673	
674	/// Parse the short flags and find the first `takes_values` option.
675	///
676	/// The returned bool is `true` only when every scanned cluster member was a
677	/// recognized option. Anything after the first value-taking option is the
678	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
679	/// characters make the result `false`.
680	fn parse_shortflags<'c, 's>(
681	    cmd: &'c clap::Command,
682	    mut short: clap_lex::ShortFlags<'s>,
683	) -> (
684	    String,
685	    Option<&'c clap::Arg>,
686	    clap_lex::ShortFlags<'s>,
687	    bool,
688	) {
689	    let takes_value_opt;
690	    let mut leading_flags = String::new();
691	    let mut cluster_valid = true;
692	    // Find the first takes_values option.
693	    loop {
694	        match short.next_flag() {
695	            Some(Ok(opt)) => {
696	                leading_flags.push(opt);
697	                let found = cmd.get_arguments().find(|a| {
698	                    let shorts = a.get_short_and_visible_aliases();
699	                    let is_find = shorts.map(|v| {
700	                        let mut iter = v.into_iter();
701	                        let c = iter.find(|c| *c == opt);
702	                        c.is_some()
703	                    });
704	                    is_find.unwrap_or(false)
705	                });
706	                if let Some(opt) = found {
707	                    if opt.get_num_args().expect("built").takes_values() {
708	                        takes_value_opt = Some(opt);
709	                        break;
710	                    }
711	                } else {
712	                    cluster_valid = false;
713	                }
714	            }
715	            Some(Err(_)) => {
716	                cluster_valid = false;
717	                takes_value_opt = None;
718	                break;
719	            }
720	            None => {
721	                takes_value_opt = None;
722	                break;
723	            }
724	        }
725	    }
726	
727	    (leading_flags, takes_value_opt, short, cluster_valid)
728	}
729	
730	/// Parse the positional arguments. Return the new state and the new positional index.
731	fn parse_positional<'a>(
732	    cmd: &clap::Command,
733	    pos_index: usize,
734	    is_escaped: bool,
735	    state: ParseState<'a>,
736	) -> (ParseState<'a>, usize) {
737	    let pos_arg = cmd
738	        .get_positionals()
739	        .find(|p| p.get_index() == Some(pos_index));
740	    let num_args = pos_arg
741	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
742	        .unwrap_or(1);
743	
744	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
745	        if num_args > 1 {
746	            (ParseState::Pos((pos_index, 1)), pos_index)
747	        } else {
748	            if is_escaped {
749	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
750	            } else {
751	                (ParseState::ValueDone, pos_index + 1)
752	            }
753	        }
754	    };
755	    match state {
756	        ParseState::ValueDone => {
757	            update_state_with_new_positional(pos_index)
758	        },
759	        ParseState::Pos((prev_pos_index, num_arg)) => {
760	            if prev_pos_index == pos_index {
761	                if num_arg + 1 < num_args {
762	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
763	                } else {
764	                    if is_escaped {
765	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
766	                    } else {
767	                        (ParseState::ValueDone, pos_index + 1)
768	                    }
769	                }
770	            } else {
771	                update_state_with_new_positional(pos_index)
772	            }
773	        }
774	        ParseState::Opt(..) => unreachable!(
775	            "This branch won't be hit,
776	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
777	        ),
778	    }
779	}
780	
781	/// Parse optional flag argument. Return new state
782	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
783	    let range = opt.get_num_args().expect("built");
784	    let max = range.max_values();
785	    if count < max {
786	        ParseState::Opt((opt, count + 1))
787	    } else {
788	        ParseState::ValueDone
789	    }
790	}
791	
792	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
793	    cmd.get_positionals()
794	        .find(|a| a.get_index() == Some(pos_index))
795	        .map(|p| p.is_allow_hyphen_values_set())
796	        .unwrap_or(false)
797	}
798	
799	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
800	    let val = arg.to_value_os();
801	    if val.starts_with("-") {
802	        if let ParseState::Opt((opt, _)) = state {
803	            return opt.is_allow_hyphen_values_set();
804	        }
805	    }
806	
807	    false
808	}
809	
810	/// Arguments that must not be offered because they conflict with an explicitly
811	/// present option. The present options themselves are never disabled.
812	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
813	    let mut disabled = HashSet::new();
814	    if explicit.is_empty() {
815	        return disabled;
816	    }
817	    for arg in cmd.get_arguments() {
818	        if explicit.contains(arg.get_id()) {
819	            // A present option hides everything it conflicts with ...
820	            for id in arg_direct_conflicts(cmd, arg) {
821	                if !explicit.contains(&id) {
822	                    disabled.insert(id);
823	                }
824	            }
825	        } else {
826	            // ... and is hidden when either side declares the conflict.
827	            if arg_direct_conflicts(cmd, arg)
828	                .iter()
829	                .any(|id| explicit.contains(id))
830	            {
831	                disabled.insert(arg.get_id().clone());
832	            }
833	        }
834	    }
835	    disabled
836	}
837	
838	/// Conflict partners of `arg`, following the same rules as clap's parser:
839	/// - the argument's own `conflicts_with` / `conflicts_with_all`
840	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
841	/// - the other members of non-`multiple` groups
842	///
843	/// Group ids are expanded to their argument members.
844	/// `overrides_with` relationships are intentionally not considered.
845	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
846	    let mut conflicts = arg
847	        .get_conflicts_with()
848	        .map(ToOwned::to_owned)
849	        .collect::<HashSet<_>>();
850	    for group in cmd.get_groups() {
851	        let members = unroll_group(cmd, group.get_id());
852	        if !members.iter().any(|m| m == arg.get_id()) {
853	            continue;
854	        }
855	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
856	        if !group.is_multiple_set() {
857	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
858	        }
859	    }
860	    conflicts
861	        .iter()
862	        .flat_map(|id| unroll_group(cmd, id))
863	        .collect()
864	}
865	
866	/// Resolve an argument or group id to its argument members.
867	/// Unknown ids resolve to themselves.
868	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
869	    let mut pending = vec![id.clone()];
870	    let mut args = Vec::new();
871	    while let Some(id) = pending.pop() {
872	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
873	            if !args.contains(&id) {
874	                args.push(id);
875	            }
876	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
877	            pending.extend(group.get_args().map(ToOwned::to_owned));
878	        } else if !args.contains(&id) {
879	            args.push(id);
880	        }
881	    }
882	    args
883	}
