use clap::{Arg, ArgAction, Command};

fn run(cmd: &mut Command, args: Vec<&str>) -> String {
    let index = args.len() - 1;
    let args: Vec<std::ffi::OsString> = args.into_iter().map(Into::into).collect();
    match clap_complete::engine::complete(cmd, args, index, None) {
        Ok(cs) => cs.iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join(" "),
        Err(e) => format!("ERR: {e}"),
    }
}

fn main() {
    // defaults / env must not record presence: `safe` has a default and env,
    // and conflicts with `fast`; `fast` must still be offered.
    let mut cmd = Command::new("exhaustive")
        .arg(Arg::new("fast").long("fast").action(ArgAction::SetTrue))
        .arg(Arg::new("safe").long("safe").env("PROBE_SAFE").default_value("true").action(ArgAction::Set).conflicts_with("fast"));
    std::env::set_var("PROBE_SAFE", "true");
    println!("default/env: {}", run(&mut cmd, vec!["exhaustive", ""]));

    // delimiter arg closed via equals records presence and its conflicts
    let mut cmd = Command::new("exhaustive")
        .arg(Arg::new("fast").long("fast").action(ArgAction::SetTrue))
        .arg(Arg::new("list").long("list").value_parser(["a","b","c"]).value_delimiter(',').conflicts_with("fast"));
    println!("delim closed: {}", run(&mut cmd, vec!["exhaustive", "--list=a,b", ""]));
    println!("delim editing: {}", run(&mut cmd, vec!["exhaustive", "--list=a,"]));

    // editing equals word of a conflicted option: prior --fast hides tag's values
    let mut cmd = Command::new("exhaustive")
        .arg(Arg::new("fast").long("fast").action(ArgAction::SetTrue))
        .arg(Arg::new("tag").long("tag").value_parser(["red","blue"]).conflicts_with("fast"));
    println!("conflicted editing: {:?}", run(&mut cmd, vec!["exhaustive", "--fast", "--tag="]));
    println!("equals closed: {}", run(&mut cmd, vec!["exhaustive", "--tag=red", ""]));

    // no_binary_name with equals first word
    let mut cmd = Command::new("exhaustive").no_binary_name(true)
        .arg(Arg::new("fast").long("fast").action(ArgAction::SetTrue))
        .arg(Arg::new("tag").long("tag").value_parser(["red","blue"]).conflicts_with("fast"));
    println!("no_binary_name: {}", run(&mut cmd, vec!["--tag=red", ""]));

    // unknown long with equals: ignored, everything offered
    println!("unknown equals: {}", run(&mut cmd, vec!["--unknown=x", ""]));

    // cursor beyond words -> existing error
    println!("beyond: {:?}", run(&mut cmd, vec!["--tag=red"]));
}
EOF
